"""Conversational framing kept separate from evidence-bearing answer claims."""

import re


def present_verified_answer(text: str, employee_message: str) -> str:
    # Preserve a greeting already generated by the model rather than duplicating it.
    if re.match(r"^(?:hi|hello|hey)\b", text.strip(), re.IGNORECASE):
        return text
    greeting = bool(re.match(r"^\s*(?:hi|hello|hey)\b", employee_message, re.IGNORECASE))
    opening = "Hello! Here's how I can help:" if greeting else "Here's some guidance to help:"
    return opening + "\n\n" + text
